export function ShadowWrapper({ children, css }: {
  children: ReactNode;
  css?: string;
}) {
  const [host, setHost] = useState<HTMLDivElement | null>(null);
  const [root, setRoot] = useState<ShadowRoot | null>(null);

  useEffect(() => {
    setRoot(host ? (host.shadowRoot ?? host.attachShadow({ mode: 'open' })) : null);
  }, [host]);

  return (
    <div ref={setHost}>
      {root && createPortal(
        <>{css && <style>{css}</style>}{children}</>,
        root,
      )}
    </div>
  );
}

